/**
 * Generates `src/components/ui/brand-paths.ts` from the Simple Icons package.
 *
 *   npm i -D simple-icons && node scripts/gen-brand-icons.mjs
 *
 * Only the marks listed in SLUGS are inlined, so the site ships a few KB of
 * path data instead of taking a runtime icon dependency. The generated file is
 * committed — `simple-icons` is only needed to regenerate it.
 *
 * Simple Icons is CC0 1.0 Universal (public domain). Each mark remains the
 * trademark of its owner and is used here only to identify the technology.
 */
import { writeFileSync } from "node:fs";
import * as si from "simple-icons";

/** local slug -> simple-icons export name */
const SLUGS = {
  openai: "siOpenai",
  python: "siPython",
  typescript: "siTypescript",
  javascript: "siJavascript",
  nodejs: "siNodedotjs",
  express: "siExpress",
  fastify: "siFastify",
  postgresql: "siPostgresql",
  supabase: "siSupabase",
  prisma: "siPrisma",
  drizzle: "siDrizzle",
  mongodb: "siMongodb",
  redis: "siRedis",
  react: "siReact",
  nextjs: "siNextdotjs",
  tailwindcss: "siTailwindcss",
  html5: "siHtml5",
  css: "siCss",
  git: "siGit",
  github: "siGithub",
  docker: "siDocker",
  vercel: "siVercel",
  linux: "siLinux",
  caddy: "siCaddy",
  n8n: "siN8n",
  telegram: "siTelegram",
  whatsapp: "siWhatsapp",
};

const entries = Object.entries(SLUGS).map(([slug, exportName]) => {
  const icon = si[exportName];
  if (!icon) throw new Error(`simple-icons has no export "${exportName}"`);
  return { slug, title: icon.title, path: icon.path };
});

const body = entries
  .map(
    ({ slug, title, path }) =>
      `  ${/^[a-z][a-z0-9]*$/.test(slug) ? slug : JSON.stringify(slug)}: {\n` +
      `    title: ${JSON.stringify(title)},\n` +
      `    path: ${JSON.stringify(path)},\n` +
      `  },`,
  )
  .join("\n");

const file = `/**
 * AUTO-GENERATED by \`node scripts/gen-brand-icons.mjs\` — do not edit by hand.
 *
 * Official technology marks, inlined from Simple Icons (CC0 1.0 Universal).
 * Every path is designed on a 24x24 viewBox and filled with \`currentColor\`,
 * so the monochrome treatment used across the site applies uniformly.
 * Each mark remains the trademark of its owner and identifies that technology
 * only.
 */

export const brandPaths = {
${body}
} as const satisfies Record<string, { title: string; path: string }>;

export type BrandSlug = keyof typeof brandPaths;
`;

writeFileSync(new URL("../src/components/ui/brand-paths.ts", import.meta.url), file);
console.log(`wrote ${entries.length} brand marks -> src/components/ui/brand-paths.ts`);
